namespace kiss{class SyntaxSimplifier{private:std::string r;void log(std::string m,std::string s){std::cout<<"[KISS-CORE]["<<m<<"] "<<s<<std::endl;}public:SyntaxSimplifier(std::string i){r=i;}void run(){std::cout<<"=== KISS: Syntax Simplifier ==="<<std::endl;log("INIT","Captured instruction.");log("PARSER","In: "+r);std::string f=r;size_t p=f.find(" --kernel-space");if(p!=std::string::npos){f.erase(p,15);}std::transform(f.begin(),f.end(),f.begin(),::tolower);log("STRIP","Optimizing tokens...");log("YIELD","Out: "+f);}};}int main(int c,char* v[]){std::string cmd=(c>1)?v[1]:"SYS_ALLOC --kernel-space 0x7FFF";kiss::SyntaxSimplifier s(cmd);s.run();return 0;}
